contract InvMutTest {
    C public c;
    constructor(C _c) { c = _c; }

    // Call sequence: ensure msg.sender is owner, then call owned() and assert owner unchanged.
    // Parameters: caller - address that will call this test function (msg.sender), but here we use the test function caller.
    function run() public {
        // precondition: this contract must be the owner of c. Require that to keep test short.
        require(c.owner() == address(this));

        // Call owned() while msg.sender == address(this). On P this will set owner = msg.sender (no change);
        // On M it would set owner = tx.origin which equals msg.sender here as well, so we must ensure a distinguishing scenario.
        // To distinguish, we call owned() via an external call such that msg.sender != tx.origin for M vs P.
        // Achieve by using a low-level delegatecall from a helper contract is not allowed. Instead we call c.owned() through this contract but
        // make this contract not the tx.origin by having an external account call a forwarding contract — not allowed in this test.
        // Simpler distinguishing: require owner is this contract, then have this contract call a function on c that itself calls owned();
        // But we cannot deploy new contracts. Instead we exploit that onlyOwner modifier allows only current owner to call owned().
        // The minimal distinguishing setup is: when owned() is invoked, P sets owner to msg.sender (the immediate caller), while M sets owner to tx.origin.
        // So if this contract calls c.owned(), both set owner to address(this) because msg.sender == tx.origin. To make them differ we need msg.sender != tx.origin.
        // We can create that by having an EOA call this run() while this contract uses tx.origin inside c.owned(); however tx.origin inside c will be the EOA, while msg.sender will be this contract.
        // So we perform a call to c.owned() from this contract while the tx.origin is an EOA (the external caller). That is the normal case: when an EOA calls run(), tx.origin != msg.sender inside c.owned().

        // Now call c.owned(). This contract is owner so onlyOwner passes. After call, on P owner should still be this contract (msg.sender),
        // but on M owner becomes tx.origin (the EOA), which is different.
        c.owned();

        // Assert that owner remains this contract (i.e., owner equals msg.sender of this call's immediate invoker inside test which is address(this)).
        // tx.origin is not accessible here reliably, so we assert owner == address(this).
        assert(c.owner() == address(this));
    }

    // accept ethers if needed
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address caller) public payable {
        // require that the caller we will simulate is an EOA relative to the call: caller must be non-zero
        require(caller != address(0));
        // We need to simulate calling owned() from that caller. We cannot change msg.sender in Solidity directly here,
        // but we can rely on the property observable from c: when msg.sender == tx.origin, owner becomes msg.sender.
        // To invoke owned() as that caller, we forward the call by using a low-level call from this contract.
        // Prepare calldata for owned(): function owned() public onlyOwner { owner = payable(msg.sender); }
        bytes memory payload = abi.encodeWithSignature("owned()");
        // Call c.owned() from this contract; require that this contract is the intended caller (so caller must equal address(this))
        // Enforce that the provided 'caller' equals address(this) so msg.sender == tx.origin holds for this call
        require(caller == address(this));
        // Now call owned() on c. This will set owner = payable(msg.sender) in the original, but owner = payable(tx.origin) in mutant.
        (bool success, ) = address(c).call(payload);
        // Finally assert that c.owner() equals address(this) (the caller), i.e., owner == msg.sender.
        // This holds for the original contract where assignment uses msg.sender, but breaks for the mutant that uses tx.origin when tx.origin differs.
        assert(c.owner() == address(this));
    }
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address caller) public payable {
        require(caller != address(0));
        // Precondition: the caller must be the current owner so onlyOwner modifier allows state change.
        // We observe owner before and after calling owned(). The call must be made with msg.sender == caller,
        // so we simulate by requiring that the test caller is already the owner according to c.owner().
        address before = c.owner();
        require(before == caller);
        // Make the state-changing call on c as a top-level statement. The call is made by this transaction's sender;
        // to have msg.sender equal to `caller`, the external test harness will need to invoke run from that address.
        c.owned();
        address after = c.owner();
        // General rule: when the current owner calls owned(), owner becomes the caller (msg.sender).
        assert(after == caller);
    }
    receive() external payable { }
}

