    function run() public payable {
        // Precondition: this caller must be the current owner so onlyOwner modifier allows the call
        require(c.owner() == msg.sender);
        // Call the function that should set owner to msg.sender in the original contract
        c.owned();
        // After the call, owner must equal the immediate caller (msg.sender). The mutant that uses tx.origin will fail if msg.sender != tx.origin.
