pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }

    // fuzzed params: an address that will act as a contract caller and an amount to burn
    function testFuzz_property(address callerContract, uint256 burnAmount) public {
        // keep callerContract non-zero to be an admissible contract address
        vm.assume(callerContract != address(0));
        // Deploy a tiny helper contract at the provided address by using CREATE2 deterministic deploy
        // because fuzzed raw address won't have code. We craft a minimal deployer that returns the new address
        // but to keep things simple and within allowed cheatcodes, deploy the helper normally and ignore callerContract
        // instead we ensure we use a contract caller (not EOA) so difference between msg.sender and tx.origin can appear.

        // Deploy a Caller helper that will call c.burn on behalf of its deployer
        Caller caller = new Caller(address(c));

        // fund owner (deployer) and set up balances so burn succeeds
        // The constructor of C set owner to this test contract's address; ensure that this test contract is owner
        // c was deployed in setUp() by this test contract, so address(this) is owner and has totalSupply (0 * ... = 0)
        // To allow burn to succeed for fuzzed burnAmount, give this test contract sufficient balance by minting via owner
        // onlyOwner functions require msg.sender == owner; since this test is owner we can mint
        // bound burnAmount to a reasonable range to avoid underflow in setup
        uint256 amount = bound(burnAmount, 0, type(uint256).max / 2);

        // mint some tokens to this test contract (owner) so burn can succeed
        c.mintToken(address(this), amount);

        // record owner before calling burn
        address ownerBefore = c.owner();

        // Now have an external contract (Caller) invoke burn on c. This makes tx.origin == address(this) and msg.sender == Caller
        // This distinguishes tx.origin vs msg.sender behavior in the mutant.
        // Ensure Caller has no ETH necessary; perform the call
        caller.doBurn(amount);

        // record owner after calling burn
        address ownerAfter = c.owner();

        // The correct contract should preserve owner across this operation for all inputs
        assertTrue(ownerBefore == ownerAfter);
    }
}

// Helper contract that calls c.burn on behalf of its deployer (so msg.sender != tx.origin)
contract Caller {
    C immutable c;
    constructor(address _c) {
        c = C(_c);
    }
    function doBurn(uint256 amt) external {
        // simply forward the call; tx.origin will be the original EOA that triggered this call
        c.burn(amt);
    }
}

