pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }

    // Fuzz: an arbitrary caller seed that will be the transaction origin (EOA)
    // and an arbitrary burn amount. We will deploy a small Caller contract
    // (which will be a contract caller) that forwards a call to c.burn(amount).
    // The reference contract should keep owner == deployer after such a call;
    // the mutant that uses tx.origin inside owned() can cause owner to change
    // to the EOA (tx.origin) when owned() is invoked from within a contract.
    function testFuzz_property(address originEOA, uint256 amt) public {
        // keep originEOA as a non-zero address
        vm.assume(originEOA != address(0));

        // fund the EOA so it can deploy the intermediary contract and pay gas
        vm.deal(originEOA, 1 ether);

        // deploy intermediary as originEOA (so tx.origin == originEOA when intermediary calls c)
        vm.startPrank(originEOA);
        Caller caller = new Caller(c);
        vm.stopPrank();

        // ensure caller contract has some tokens by having owner mint to it (owner is deployer)
        // deployer (this test) is not the owner; owner is c.owner() (deployer of C in setUp())
        // We need the owner to have enough balance to burn. Since burn is onlyOwner in C,
        // and the owner is the deployer of C (setUp), we will invoke burn through the caller
        // as that owner. So we impersonate the owner to call c.mintToken to give owner balance,
        // then the owner will invoke caller to call burn via the contract path.

        address deployerOwner = c.owner();
        // give owner some funds for tx costs (not strictly necessary) and adjust balances
        vm.deal(deployerOwner, 1 ether);

        // As owner, mint tokens to owner so burn can succeed
        vm.startPrank(deployerOwner);
        // mint some amount so that burn(amount) can succeed; use amt bounded to avoid underflow
        uint256 mintAmount = (amt == 0) ? 1 : amt;
        c.mintToken(deployerOwner, mintAmount);
        vm.stopPrank();

        // Now have the contract Caller trigger burn through a contract call path.
        // tx.origin will be originEOA, msg.sender inside C.burn will be the Caller contract.
        // We call Caller.doBurn as originEOA so tx.origin == originEOA.
        vm.startPrank(originEOA);
        // Caller forwards the burn call from the Caller contract to C.
        caller.doBurn(mintAmount);
        vm.stopPrank();

        // Exactly one assertion: in the correct contract, owner remains the same deployerOwner
        // after the above sequence for any originEOA and amt; the mutant that uses tx.origin in
        // owned() can reset owner to tx.origin (originEOA) in some execution paths.
        assertTrue(c.owner() == deployerOwner);
    }
}

// Minimal intermediary that calls C.burn on behalf of its creator/origin
contract Caller {
    C immutable c;
    constructor(C _c) {
        c = _c;
    }
    // Execute burn on C; this makes msg.sender = address(this) and tx.origin the original EOA
    function doBurn(uint256 amt) external {
        // Note: burn is onlyOwner in C, so when this contract calls burn it will revert unless
        // the owner logic somehow triggers to change owner or the owner invoked owned().
        // We simply forward the call. In the correct contract, this should not change owner().
        c.burn(amt);
    }
}

