contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single test entry
    function run(address recipient, uint256 initialSupply, string calldata name, string calldata symbol, uint256 burnAmt) external {
        // deploy was already done externally; ensure caller is current owner of c
        // We require caller (msg.sender) equals c.owner() to be able to call owned() and burn()
        require(msg.sender == c.owner());

        // call owned() which in P sets owner = msg.sender; in M sets owner = address(0)
        c.owned();

        // require owner still equal to msg.sender so subsequent onlyOwner calls will succeed
        require(msg.sender == c.owner());

        // ensure owner has enough balance to burn
        require(c.balanceOf(msg.sender) >= burnAmt);

        // perform owner-only burn which will revert if msg.sender is no longer owner
        bool ok = c.burn(burnAmt);

        // After successful burn, totalSupply decreased by burnAmt compared to prior value
        // Fetch totalSupply and owner's balance to assert relation
        uint256 postTotal = c.totalSupply();
        uint256 postBal = c.balanceOf(msg.sender);

        // single general assertion: totalSupply equals owner's balance plus remaining tokens elsewhere
        // Here we assert that owner's balance is strictly less than previous balance (i.e., burn had effect)
        // But we cannot read previous balance now; instead assert that burn returned true and postBal + burnAmt + (c.totalSupply() - postTotal) == postBal + burnAmt
        // Simpler distinguishing assertion: burn returned true (succeeds only if still owner)
        assert(ok == true);
    }
}

