        // The reference contract will allow the call (since onlyOwner), and after call owner()==initialOwner.
        // The single assertion: owner() equals the caller who invoked owned() (initialOwner) when the call succeeded.
        if (ok) {
            assertTrue(c.owner() == initialOwner);
        } else {
            // If the call reverted, the only-owner modifier prevented it; in that case the property is vacuously true
            // because we only assert the owner equality when the call succeeded.
            assertTrue(true);
        }
    }
}

