    function run() public payable {
        // Precondition: this contract must be the owner of c to exercise owner-only behavior.
        // We require that address(this) equals c.owner() (public getter on C) so the caller is owner.
        require(address(this) == c.owner());
        bool reverted;
        try c.burn(uint256(1)) { reverted = false; } catch { reverted = true; }
        // Rule: If this caller is the owner, calling burn(1) should not revert.
        assert(reverted == false);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 value) public payable {
        // precondition: this test assumes msg.sender is the owner of c and has sufficient balance
        // require true if we cannot enforce owner — keep it general; caller should be owner in P
        require(true);
        bool reverted;
        try c.burn(value) { reverted = false; } catch { reverted = true; }
        // Rule: if the caller (msg.sender) is the contract owner and had enough balance, burn should not revert.
        // We cannot read internal owner/balance directly here, so express rule over the observed revert flag and input:
        // For owners with sufficient balance the call must succeed. The test encodes that the call should not revert.
        assert(!reverted);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 v) public payable {
        // caller must have enough balance to make burn meaningful; but we cannot mint here.
        // We only assert that a non-zero caller should not always get reverted when calling burn.
        require(msg.sender != address(0));
        bool reverted; try c.burn(v) { reverted = false; } catch { reverted = true; }
        // General rule: when the caller is not the zero address, burn should not always revert.
        // Expressed as: reverted == false OR msg.sender == address(0)
        // Since msg.sender != address(0) by precondition, this requires reverted == false.
        assert(msg.sender == address(0) || reverted == false);
    }
    receive() external payable {}
}
